package com.jarvis.fa;
import android.app.*;import android.content.*;import android.hardware.camera2.*;import android.net.*;
public class JarvisActions{private final Activity a;public JarvisActions(Activity x){a=x;}public boolean openUrl(String u){try{a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));return true;}catch(Exception e){return false;}}public boolean webSearch(String q){return openUrl("https://www.google.com/search?q="+Uri.encode(q));}public boolean openMaps(String q){try{a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("geo:0,0?q="+Uri.encode(q))));return true;}catch(Exception e){return false;}}public boolean dial(String n){try{a.startActivity(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:"+Uri.encode(n))));return true;}catch(Exception e){return false;}}public boolean openApp(String pkg){try{Intent i=a.getPackageManager().getLaunchIntentForPackage(pkg);if(i==null)return false;a.startActivity(i);return true;}catch(Exception e){return false;}}public boolean settings(String action){try{a.startActivity(new Intent(action));return true;}catch(Exception e){return false;}}public boolean flashlight(boolean on){try{CameraManager cm=(CameraManager)a.getSystemService(Context.CAMERA_SERVICE);for(String id:cm.getCameraIdList()){try{cm.setTorchMode(id,on);return true;}catch(Exception ignored){}}}catch(Exception ignored){}return false;}}
